mapper.select:
SELECT id, prefix_number, description, sort_order, course_id, group_learning_outcome_id, created_at, updated_at
FROM edu.learning_outcomes
WHERE id = #{id}

mapper.delete:
DELETE FROM edu.learning_outcomes
WHERE id IN

  #{id}

mapper.update:
UPDATE edu.learning_outcomes
SET group_learning_outcome_id = #{groupId},
    updated_at = NOW()
WHERE id = #{id}
  AND course_id = #{courseId}

mapper.select:
SELECT COALESCE(MAX(sort_order), 0)
FROM edu.learning_outcomes
WHERE group_learning_outcome_id = #{groupId}

